const headings = ['Name the decision','Describe the starting material','Set the safe first move','Make evidence visible','Separate routine from exception','Design the review moment','Write the cross-time-zone handoff','Check the permission boundary','Learn from correction','Close with the owner action'];

function paragraph(s: Spec, i: number): string {
  const starts = [
    `For ${s.focus}, begin with the decision the owner needs to make rather than with a broad request to “help.” ${s.audience} needs ${s.result}. Write that outcome in one sentence, then list what will count as ready for review. The description should be concrete enough that an assistant can prepare the work and a second person can inspect it without guessing. ${s.lens} matters because a queue can look busy while still hiding the actual choice.`,
    `The starting material for ${s.focus} is ${s.object}. Record where it came from, when it was last checked, and which parts are missing. Then apply the first move: ${s.first}. A brief that names the input prevents the assistant from searching every connected tool or treating an old message as current authority. It also gives the owner a fair way to distinguish incomplete input from incomplete work.`,
    `The first safe move should be small enough to reverse. In this case, it means ${s.first}. Give the assistant one ordinary example and one example that must stop. The point is not to script every sentence; it is to show the boundary between preparation and decision. A Philippines-based assistant can work independently inside a defined lane when the lane includes its trigger, source, expected record, and next reviewer.`,
    `Make the evidence visible beside the work. For ${s.focus}, preserve the request, relevant source, action taken, unresolved question, and current state. Do not make the reviewer infer why an item was changed. If a fact is unavailable, label it unavailable. If a statement is an interpretation, label it as a proposed reading. This protects customer-facing copy, internal reporting, and future handoffs from a confident sentence that has no traceable basis.`,
    `Routine work ends when it reaches the agreed result; the exception begins when the request changes its consequence. The important exception here is ${s.failure}. When it appears, pause the consequential step, retain the surrounding context, and ask the named owner a narrow question. The assistant may suggest safe preparation, but it should not convert urgency, repetition, or a missing reply into authority.`,
    `Review should happen at the point where a mistake would become expensive or public. Inspect a representative sample for completeness, source handling, status accuracy, and boundary judgment. For ${s.focus}, ask whether another reviewer could tell what happened and what decision remains. Correct the record itself when necessary, then correct the brief if the same ambiguity could return. A review is useful when it improves the next item, not when it merely assigns blame.`,
    `A time-zone gap makes the handoff part of the work. End the shift with completed items, items waiting on evidence, blocked items, and one explicit next owner. Mention the relevant date, local time, and source record when timing matters. Avoid “please review” as a standalone instruction; state the choice needed. The next person should be able to continue ${s.focus} without opening scattered chats or assuming that silence means approval.`,
    `Tools should follow the role rather than define it. Map each action as view, draft, edit, send, approve, or delete. Grant only what is needed for the current lane, use individual accounts where possible, and retain owner control over irreversible changes. The boundary here is ${s.boundary}. If the role expands, review the new access, training, and approval path together instead of adding a permission as a quick fix.`,
    `After several cycles, review the correction pattern. Was the source unclear, the example incomplete, the status vocabulary inconsistent, or the owner unavailable? Store the answer in ${s.object} or the role brief, and note who approved the change. This is especially important for outsourced support: the assistant should not be judged against a private rule that was never written, while the owner should not have to repeat the same correction forever.`,
    `The owner action is to test one real but bounded item, inspect the evidence, confirm the stop condition, and decide whether the lane is ready for more volume. Do not treat this method as a guarantee or as legal, tax, financial, employment, medical, or security advice. For ${s.focus}, the durable outcome is a clearer handoff: useful preparation from the assistant, visible uncertainty, and consequential judgment retained by the authorized owner.`
  ];
  return starts[i];
}

const repairNotes: Record<string, string> = {
  'outsourced-assistant-weekly-capacity-map': `A useful capacity map also records what is deliberately not scheduled. For each recurring duty, note the assumed frequency, the effort range, the input that must arrive first, and the person who can change the priority. A Philippines-based assistant can prepare this inventory and flag collisions, but should not resolve a collision by silently dropping a committed item. The owner can choose to defer, delegate, shorten, or remove work, and that choice belongs in the Monday planning note. Keep a small reserve for questions and corrections; treating every minute as committed makes the map look precise while hiding normal operating variance. When a new request arrives, compare it with the map, record the conflict, and state the decision needed. This turns capacity into a shared fact rather than a personal judgement about an outsourced assistant. Recheck the map after one week and revise the effort assumptions from observed evidence, not optimism.`,
  'filipino-virtual-assistant-escalation-ladder': `An escalation ladder works when it gives the assistant enough structure to ask a smaller question. The card should capture the request, relevant account or record, known facts, uncertainty, possible impact, urgency, and the decision that only the reviewer can make. Separate routine clarification from a policy exception, payment issue, customer complaint, or access concern. A Filipino virtual assistant may gather the approved context and draft the question; the ladder must not turn a quiet reviewer into implied approval. Set a response window and a backup path, then state what happens when both are unavailable: preserve the record, pause the consequential action, and notify the owner through the approved channel. Review a sample of escalations for missing context and unnecessary escalation. If the same question repeats, improve the card or source instruction. The measure of a good ladder is not fewer questions; it is better-scoped questions that preserve authority and make the next decision easier.`,
  'outsourced-assistant-knowledge-base-review': `Review the knowledge base by following real assistant questions from intake to answer. Record the exact question, the source document, its owner, its last review date, the answer supported by that source, and any conflict with another instruction. A short register is more useful than a large collection of pages that no one can distinguish. The outsourced assistant can identify duplicates, mark stale material, and draft a proposed replacement, but the policy owner approves the meaning of a corrected answer. Do not reward speed when the source is contradictory. A safe response is to preserve the question, explain that the answer is under review, and escalate the decision. Check whether permissions, links, examples, and escalation contacts still match the current lane. Review a new sample after the register changes and retire only material that has an identified replacement or an explicit owner decision. This makes consistency a property of the source system, not a demand that a Filipino assistant remember every informal instruction.`,
  'remote-assistant-shift-handoff': `A remote shift handoff should be written for someone who was not present. Name the route or queue, the last completed action, the exact evidence location, the next safe action, and the point at which work must stop. Use an absolute date and time with a stated time zone when a deadline matters. An outsourced assistant can prepare the note, reconcile statuses, and identify a missing reply; the next person still needs the authority to approve a customer-facing or irreversible action. Keep waiting, blocked, drafted, approved, and complete as separate states. A sentence such as “all good” hides the difference between no issue and no review. The owner should sample handoffs for recoverability: could another assistant continue without reopening private chat history? If not, update the handoff template or SOP. A good remote routine respects the Filipino assistant’s working context while keeping decisions with the named owner, regardless of who happens to be online.`,
  'outsourced-assistant-approval-queue': `An approval queue is a decision boundary, not just a list of tasks. Each item should show what is being requested, the source evidence, the proposed action, the consequence of waiting, the person who may approve it, and the required response format. An outsourced assistant can assemble a complete packet, check that required fields are present, and return an item for missing context. It should not move an item to approved because a deadline is close or because the owner has approved a similar item before. Use separate statuses for ready for review, changes requested, approved, rejected, and expired. Keep the original request attached when the draft changes so the reviewer can see what was altered. Sample the queue for stale approvals and duplicate records, then improve the intake rule that caused them. This gives a Filipino virtual assistant a clear preparation lane while protecting the owner’s responsibility for money, policy, customer promises, or public claims.`,
  'filipino-assistant-data-cleanup-scope': `Data cleanup needs a written definition of what may change and what must remain untouched. Start with a field map that names the source, allowed format, duplicate rule, missing-value treatment, and review owner. A Filipino assistant may normalize an approved spelling, flag a likely duplicate, or prepare a change list. Deletion, merging, history changes, and edits to fields used for forecasts or commitments require an explicit decision. Preserve the before value and reason for every non-trivial change, even when the system provides an audit log. Test a small sample against the source record before expanding the lane. If two records disagree, do not choose the more convenient value; retain both evidence points and escalate the ambiguity. The owner can then decide whether to correct, defer, or leave the record unchanged. Review the cleanup by accuracy, traceability, and escalation judgment, not by the number of rows touched. A bounded scope protects both reporting and the outsourced assistant from invisible assumptions.`,
  'outsourced-assistant-research-brief': `A research brief becomes useful when every material statement has a visible path back to evidence and a stated limit. Begin with the decision question, population or subject, date range, source type, and interpretation the owner needs. An outsourced assistant can discover sources, record passages, compare definitions, and draft open questions. The owner decides whether the evidence is sufficient for a public claim, a policy change, or another consequential use. Keep search leads separate from sources that actually support a conclusion. For each source, note why it is relevant, what it cannot establish, and whether its data or guidance is current enough for this question. If sources disagree, describe the disagreement instead of smoothing it into a confident sentence. The brief should end with a recommended next review, not a manufactured certainty. A Filipino assistant working on research can make the evidence easier to inspect while the accountable reviewer retains interpretation, publication, and risk decisions.`,
  'outsourced-assistant-meeting-prep-packet': `A meeting-prep packet should help the owner decide what deserves time before the call begins. Include the purpose, participants, relevant prior decisions, open questions, documents, proposed agenda, and the decision or input requested from each attendee. An outsourced assistant can gather approved materials, check links, draft neutral questions, and identify missing context. It should not invent a participant position, promise an outcome, or circulate sensitive material beyond the approved list. Mark facts, assumptions, and proposed discussion points separately. If a preparation source is stale or contradictory, flag it beside the affected agenda item and ask the owner which version governs. After the meeting, connect the packet to the approved notes and action queue so the preparation does not become an orphaned document. Review whether the packet reduced searching and exposed the real decision. This gives a Filipino assistant a concrete administrative lane while leaving prioritization, commitments, and sensitive judgement with the owner.`,
  'outsourced-assistant-vendor-follow-up': `Vendor follow-up should distinguish a status request from a change to an obligation. The assistant can verify the known contact, quote the existing request, ask for a delivery update, record the response, and prepare an escalation when the supplier misses an agreed checkpoint. It should not accept a substitute, revised price, changed payment term, or new delivery promise unless the owner has explicitly granted that authority. Keep the original commitment, supplier reply, proposed change, evidence link, and decision needed together. If a message arrives from an unfamiliar address or asks for sensitive information, verify it through a known channel before replying. A Philippines-based operations assistant can keep the queue current and make unanswered requests visible without becoming the commercial decision-maker. Review a sample for accurate status wording, correct contact handling, and clean escalation. When the same vendor question returns, update the record or follow-up script with the smallest durable clarification.`,
  'outsourced-assistant-quality-sample-plan': `A quality sample plan should tell the reviewer what to inspect and why the sample represents the lane. Define the work population, selection rule, review frequency, criteria, severity levels, and action for a failed sample. An outsourced assistant should see the criteria before work begins; changing the standard after a return makes coaching arbitrary. Score accuracy, completeness, source use, tone, timeliness, and escalation judgment only where each criterion is relevant. Preserve a short note explaining the evidence behind each score and separate a process defect from a one-off mistake. A Filipino assistant can help collect samples and record corrections, while the owner decides whether the SOP, training, access, or scope needs to change. Do not use a score as a hidden proxy for personality or availability. Recheck the plan after several samples: if reviewers disagree, clarify the example or scoring rule. The goal is a fair, inspectable feedback loop that improves delegated work without inventing a performance claim.`,
  'filipino-virtual-assistant-calendar-timezone-rules': `Calendar rules should store a canonical time zone, the displayed local time, the participant’s confirmed zone, and the conversion used for the invitation. Never rely on “tomorrow morning” when a distributed team is involved. A Filipino virtual assistant can compare availability, draft options, check daylight-saving implications where relevant, and send a confirmation only within the approved lane. Moving a high-stakes meeting, changing a customer commitment, or overriding an owner’s protected time requires approval. Put the date, time, zone, duration, location or link, and preparation requirement in the confirmation format. When a participant gives an ambiguous time, preserve the message and ask for the zone rather than guessing. Review a sample of bookings for conversion accuracy and for whether the written record would let another assistant reconstruct the decision. A clear calendar routine reduces avoidable confusion while keeping priority and commitment decisions with the owner.`,
};

function makePost(s: Spec, index: number): BlogPost {
  return { slug: s.slug, title: s.title, published: '2026-08-21', minutes: 11,
    excerpt: `A practical OutsourcingAssistant.com guide for ${s.audience}: make ${s.focus} reviewable, useful, and bounded.`,
    takeaway: `${s.result}. Start with ${s.first}, and keep ${s.boundary} with the owner.`,
    image: { url: `/images/blog-2026-08-21/${s.slug}.png`, alt: s.title },
    sections: [...headings.map((heading, i) => ({ heading, body: paragraph(s, (i + index) % 10) })), { heading: 'Route-local operating guidance', body: `${s.evidence}\n\n${repairNotes[s.slug] ?? ''}` }],
    faqs: [
      { q: `What should the owner define before delegating ${s.focus}?`, a: `Define the input, finished result, source of truth, review point, and the action that remains with the owner: ${s.boundary}.` },
      { q: 'What should happen when the normal path breaks?', a: `Pause the consequential step, keep the relevant evidence, and route a concise question to the named reviewer. Do not guess because the request is urgent.` },
      { q: 'How can a distributed team improve the routine?', a: 'Review a small representative sample, record corrections, and update the brief or example when the same ambiguity returns.' }
    ],
    internalLinks: [{ href: '/resources/assistant-sop-handoff-checklist', label: 'Use the assistant SOP handoff checklist' }, { href: '/services', label: 'Review staffing and support services' }]
  };
}

export const dailyBlogBatch20260821: BlogPost[] = specs.map(makePost);
